"use client"

import { useEffect, useMemo, useState } from "react"
import { useQuery, QueryClient, QueryClientProvider } from "@tanstack/react-query"
import { Area, AreaChart, Bar, BarChart, CartesianGrid, Cell, PolarAngleAxis, PolarGrid, Radar, RadarChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts"
import { Activity, ArrowDownRight, ArrowRight, ArrowUpRight, Bell, BookOpen, BriefcaseBusiness, ChartNoAxesCombined, Check, ChevronDown, ChevronLeft, ChevronRight, CircleHelp, Clock3, Download, Filter, Goal, Heart, LayoutDashboard, LogOut, Menu, Moon, MoreHorizontal, Plus, Search, Settings, ShieldCheck, SlidersHorizontal, Sparkles, Star, Sun, Target, TrendingUp, Users, X } from "lucide-react"
import { clubs, competitions, historyForPlayer, initialReports, players, userFree, userPremium } from "@/src/mocks/data"
import type { Player, PlayerFilters, Position, Report } from "@/src/types/domain"
import { getKnownPlayers, playerRepository, usingApi } from "@/src/repositories/player-repository"
import { authService, favoritesService, reportsService, subscriptionService } from "@/src/services/demo-services"
import { Button } from "@/components/ui/button"
import { Toaster, toast } from "sonner"

const queryClient = new QueryClient({ defaultOptions: { queries: { staleTime: 30_000, retry: 1 } } })
type Page = "home" | "dashboard" | "players" | "player" | "compare" | "clubs" | "club" | "reports" | "favorites" | "plan" | "settings" | "pricing"
const navGroups = [
  { label: "VISÃO GERAL", items: [{ id: "dashboard" as Page, label: "Dashboard", icon: LayoutDashboard }] },
  { label: "SCOUTING", items: [{ id: "players" as Page, label: "Explorar atletas", icon: Search }, { id: "clubs" as Page, label: "Clubes", icon: ShieldCheck }, { id: "compare" as Page, label: "Comparar atletas", icon: ChartNoAxesCombined }] },
  { label: "ESPAÇO DE TRABALHO", items: [{ id: "favorites" as Page, label: "Favoritos", icon: Heart }, { id: "reports" as Page, label: "Relatórios", icon: BookOpen }] },
]
const fmt = (value: number) => new Intl.NumberFormat("pt-BR").format(value)
const clubFor = (value: string | Player) => {
  const id = typeof value === "string" ? value : value.clubId
  const apiPlayer = typeof value === "string" ? getKnownPlayers().find((player) => player.clubId === id) : value
  return clubs.find((club) => club.id === id) || {
    id,
    name: apiPlayer?.clubName || "Clube não informado",
    state: apiPlayer?.clubState || "BR",
    competitionId: apiPlayer?.competitionId || "serie-d",
    season: apiPlayer?.season || new Date().getFullYear().toString(),
    color: "#102a72",
  }
}
const compFor = (value: string | Player) => {
  const id = typeof value === "string" ? value : value.competitionId
  const apiPlayer = typeof value === "string" ? getKnownPlayers().find((player) => player.competitionId === id) : value
  return competitions.find((item) => item.id === id) || { id, name: apiPlayer?.competitionName || "Competição não informada", level: "Não informado" }
}
const initials = (name: string) => name.split(" ").map((part) => part[0]).slice(0, 2).join("")

export default function FutMathApp() {
  return <QueryClientProvider client={queryClient}><FutMathShell /><Toaster position="top-right" richColors /></QueryClientProvider>
}

function FutMathShell() {
  const [page, setPage] = useState<Page>("home")
  const [user, setUser] = useState<typeof userFree | null>(null)
  const [favoriteIds, setFavoriteIds] = useState<string[]>([])
  const [comparisonIds, setComparisonIds] = useState<string[]>([])
  const [selectedPlayer, setSelectedPlayer] = useState(players[0])
  const [selectedClub, setSelectedClub] = useState(clubs[0])
  const [dark, setDark] = useState(false)
  const [mobileNav, setMobileNav] = useState(false)
  const [reports, setReports] = useState<Report[]>(initialReports)
  const [quotaTick, setQuotaTick] = useState(0)
  const quota = subscriptionService.getUsageQuota(user?.plan || "Free")
  const catalogQuery = useQuery({
    queryKey: ["player-catalog"],
    queryFn: () => playerRepository.listPlayers({}, { page: 1, pageSize: 1_000 }),
    enabled: Boolean(user),
    retry: false,
  })
  const playerCatalog = catalogQuery.data?.items || players
  useEffect(() => {
    const syncRoute = () => {
      const route = window.location.pathname.slice(1) || "home"
      const pages: Page[] = ["home", "dashboard", "players", "player", "compare", "clubs", "club", "reports", "favorites", "plan", "settings", "pricing"]
      if (pages.includes(route as Page)) setPage(route as Page)
    }
    window.addEventListener("popstate", syncRoute)
    return () => window.removeEventListener("popstate", syncRoute)
  }, [])

  const go = (next: Page) => { setPage(next); setMobileNav(false); if (typeof window !== "undefined") window.history.pushState({ page: next }, "", next === "home" ? "/" : `/${next}`); window.scrollTo({ top: 0, behavior: "smooth" }) }
  const loadDemo = async (plan: "Free" | "Premium" = "Free") => { const profile = await authService.signIn(plan); setUser(profile); setFavoriteIds(favoritesService.get()); setReports([...initialReports, ...reportsService.get()]); go("dashboard") }
  const toggleFavorite = (id: string) => { const next = favoritesService.toggle(id); setFavoriteIds(next); toast.success(next.includes(id) ? "Atleta adicionado aos favoritos" : "Atleta removido dos favoritos") }
  const consume = () => { if (!subscriptionService.consumeQuery(user?.plan || "Free")) { toast.error("Cota diária atingida", { description: "O plano Free permite 100 consultas por dia. Conheça o Premium para continuar." }); return false } setQuotaTick((n) => n + 1); return true }
  const openPlayer = (player: Player) => { setSelectedPlayer(player); go("player") }
  const toggleCompare = (id: string) => { setComparisonIds((current) => { if (current.includes(id)) return current.filter((item) => item !== id); if (current.length >= 4) { toast.error("A comparação aceita até 4 atletas"); return current } return [...current, id] }) }
  const createReport = () => {
    if (comparisonIds.length < 2) { toast.error("Selecione pelo menos dois atletas para gerar o relatório"); return }
    const report: Report = { id: `relatorio-${Date.now()}`, title: `Comparação de ${comparisonIds.length} atletas`, type: "Comparação", createdAt: new Date().toISOString().slice(0, 10), playerIds: comparisonIds, season: "2025" }
    setReports((current) => [report, ...current]); reportsService.save(report); toast.success("Relatório criado", { description: "Seus dados comparativos estão prontos para exportação." }); go("reports")
  }
  const deleteReport = (id: string) => { if (!window.confirm("Deseja excluir este relatório?")) return; setReports((current) => current.filter((report) => report.id !== id)); reportsService.remove(id); toast.success("Relatório excluído") }
  const exportReport = (report: Report) => {
    const rows = report.playerIds.map((id) => playerCatalog.find((player) => player.id === id)).filter(Boolean) as Player[]
    const content = `<html lang="pt-BR"><meta charset="utf-8"><title>${report.title}</title><style>body{font:14px Arial,sans-serif;color:#10213f;padding:36px}h1{color:#102a72}table{border-collapse:collapse;width:100%;margin:24px 0}td,th{border:1px solid #dbe2ee;padding:10px;text-align:left}small{color:#64748b}.tag{color:#26885f}</style><h1>FutMath · Relatório de scouting</h1><h2>${report.title}</h2><small>Temporada ${report.season} · Gerado em ${new Date(report.createdAt).toLocaleDateString("pt-BR")}</small><table><thead><tr><th>Atleta</th><th>Clube</th><th>Posição</th><th>Jogos</th><th>Minutos</th><th>Gols</th><th>Assist.</th><th>Índice</th></tr></thead><tbody>${rows.map((p) => `<tr><td>${p.name}</td><td>${clubFor(p).name}</td><td>${p.position}</td><td>${p.appearances}</td><td>${p.minutes}</td><td>${p.goals}</td><td>${p.assists}</td><td>${p.rating.toFixed(1)}</td></tr>`).join("")}</tbody></table><small>Fonte: ${usingApi ? "FutMath API" : "Base demonstrativa FutMath"}.</small><script>window.onload=()=>window.print()</script></html>`
    const popup = window.open("", "_blank"); if (popup) { popup.opener = null; popup.document.write(content); popup.document.close() } else toast.error("Permita pop-ups para exportar o PDF")
  }

  if (page === "home" || page === "pricing" || !user) return <Landing onLogin={() => go("settings")} onDemo={loadDemo} onPricing={() => go("pricing")} pricing={page === "pricing"} />

  const sharedProps = { user, page, go, dark, setDark, mobileNav, setMobileNav, favoriteIds, toggleFavorite, comparisonIds, toggleCompare, quota, quotaTick, consume, openPlayer, selectedPlayer, selectedClub, setSelectedClub, reports, setReports, createReport, deleteReport, exportReport, playerCatalog }
  return <div className={dark ? "dark min-h-screen" : "min-h-screen"}>
    <div className="flex min-h-screen bg-[#f5f7fb] text-[#16213b] dark:bg-[#0b1220] dark:text-slate-100">
      <Sidebar {...sharedProps} onLogout={() => { setUser(null); go("home") }} />
      <main className="min-w-0 flex-1 lg:ml-[248px]">
        <Topbar {...sharedProps} onLogout={() => { setUser(null); go("home") }} />
        <div className="mx-auto max-w-[1440px] px-4 pb-12 pt-6 sm:px-7 lg:px-9">
          {page === "dashboard" && <Dashboard {...sharedProps} />}
          {page === "players" && <PlayersPage {...sharedProps} />}
          {page === "player" && <PlayerPage {...sharedProps} />}
          {page === "compare" && <ComparePage {...sharedProps} />}
          {page === "clubs" && <ClubsPage {...sharedProps} />}
          {page === "club" && <ClubPage {...sharedProps} />}
          {page === "favorites" && <FavoritesPage {...sharedProps} />}
          {page === "reports" && <ReportsPage {...sharedProps} />}
          {page === "plan" && <PlanPage {...sharedProps} />}
          {page === "settings" && <SettingsPage {...sharedProps} />}
        </div>
      </main>
    </div>
  </div>
}

type Shared = { user: typeof userFree; page: Page; go: (page: Page) => void; dark: boolean; setDark: (value: boolean) => void; mobileNav: boolean; setMobileNav: (value: boolean) => void; favoriteIds: string[]; toggleFavorite: (id: string) => void; comparisonIds: string[]; toggleCompare: (id: string) => void; quota: { used: number; limit: number | null; renewsAt: string }; quotaTick: number; consume: () => boolean; openPlayer: (player: Player) => void; selectedPlayer: Player; selectedClub: (typeof clubs)[number]; setSelectedClub: (club: (typeof clubs)[number]) => void; reports: Report[]; setReports: (callback: (current: Report[]) => Report[]) => void; createReport: () => void; deleteReport: (id: string) => void; exportReport: (report: Report) => void; playerCatalog: Player[] }

function Sidebar({ page, go, user, dark, setDark, mobileNav, setMobileNav, comparisonIds, onLogout }: Shared & { onLogout: () => void }) {
  return <>
    {mobileNav && <button aria-label="Fechar menu" className="fixed inset-0 z-30 bg-black/40 lg:hidden" onClick={() => setMobileNav(false)} />}
    <aside className={`fixed inset-y-0 left-0 z-40 flex w-[248px] flex-col bg-[#102a72] text-white transition-transform lg:translate-x-0 ${mobileNav ? "translate-x-0" : "-translate-x-full"}`}>
      <div className="flex h-[76px] items-center gap-3 border-b border-white/10 px-6"><div className="flex size-9 items-center justify-center rounded-xl bg-[#2dce89] text-[#102a72]"><Activity size={21} strokeWidth={2.8} /></div><div><div className="text-[19px] font-bold tracking-tight">Fut<span className="text-[#44dfa0]">Math</span></div><div className="text-[10px] tracking-[.16em] text-white/50">SPORTS INTELLIGENCE</div></div><button className="ml-auto rounded-md p-2 lg:hidden" aria-label="Fechar menu" onClick={() => setMobileNav(false)}><X size={18}/></button></div>
      <div className="mx-4 mt-5 rounded-xl border border-white/10 bg-white/[.08] p-3"><div className="flex items-center gap-3"><div className="flex size-9 items-center justify-center rounded-full bg-[#d7f6e9] text-xs font-bold text-[#16704d]">MC</div><div className="min-w-0 flex-1"><div className="truncate text-sm font-semibold">{user.club}</div><div className="text-xs text-white/60">Plano {user.plan}</div></div><ChevronDown size={15} className="text-white/50" /></div></div>
      <nav className="mt-7 flex-1 px-3">{navGroups.map((group) => <div key={group.label} className="mb-7"><div className="mb-2 px-3 text-[10px] font-semibold tracking-[.14em] text-white/40">{group.label}</div><div className="flex flex-col gap-1">{group.items.map((item) => { const Icon = item.icon; return <button key={item.id} onClick={() => go(item.id)} className={`flex h-10 items-center gap-3 rounded-lg px-3 text-left text-[13px] transition ${page === item.id || (item.id === "players" && page === "player") || (item.id === "clubs" && page === "club") ? "bg-white text-[#102a72] font-semibold shadow-sm" : "text-white/75 hover:bg-white/10 hover:text-white"}`}><Icon size={17}/>{item.label}{item.id === "compare" && comparisonIds.length > 0 && <span className="ml-auto rounded-full bg-[#2dce89] px-2 py-0.5 text-[10px] font-bold text-[#102a72]">{comparisonIds.length}</span>}</button> })}</div></div>)}</nav>
      <div className="mx-4 mb-4 rounded-xl bg-[#0b205d] p-4"><div className="mb-2 flex items-center gap-2 text-xs font-semibold"><Sparkles size={14} className="text-[#43d99d]"/> FutMath Premium</div><p className="mb-3 text-[11px] leading-relaxed text-white/60">Mais inteligência para encontrar o próximo talento.</p><button onClick={() => go("plan")} className="w-full rounded-lg bg-[#2dce89] py-2 text-xs font-bold text-[#102a72] hover:bg-[#46dfa0]">Conhecer planos</button></div>
      <div className="border-t border-white/10 p-3"><button onClick={() => go("settings")} className="flex w-full items-center gap-3 rounded-lg px-3 py-2.5 text-sm text-white/70 hover:bg-white/10"><Settings size={17}/> Configurações</button><button onClick={() => setDark(!dark)} className="flex w-full items-center gap-3 rounded-lg px-3 py-2.5 text-sm text-white/70 hover:bg-white/10">{dark ? <Sun size={17}/> : <Moon size={17}/>} {dark ? "Modo claro" : "Modo escuro"}</button><button onClick={onLogout} className="flex w-full items-center gap-3 rounded-lg px-3 py-2.5 text-sm text-white/70 hover:bg-white/10"><LogOut size={17}/> Sair da conta</button></div>
    </aside>
  </>
}

function Topbar({ user, setMobileNav, onLogout }: Shared & { onLogout: () => void }) {
  return <header className="sticky top-0 z-20 flex h-[76px] items-center justify-between border-b border-slate-200/80 bg-white/90 px-4 backdrop-blur dark:border-slate-800 dark:bg-[#0d1728]/90 sm:px-7 lg:px-9"><div className="flex items-center gap-3"><button onClick={() => setMobileNav(true)} className="rounded-lg p-2 hover:bg-slate-100 lg:hidden" aria-label="Abrir menu"><Menu size={19}/></button><div className="hidden text-xs text-slate-400 sm:block">Workspace <span className="mx-2">/</span><span className="font-semibold text-slate-700 dark:text-slate-200">{user.club}</span></div><div className="sm:hidden text-sm font-semibold">FutMath</div></div><div className="flex items-center gap-2"><button aria-label="Ajuda" className="rounded-lg p-2.5 text-slate-500 hover:bg-slate-100"><CircleHelp size={18}/></button><button aria-label="Notificações" className="relative rounded-lg p-2.5 text-slate-500 hover:bg-slate-100"><Bell size={18}/><span className="absolute right-2 top-2 size-1.5 rounded-full bg-[#2dce89]"/></button><span className="mx-1 h-7 border-l border-slate-200"/><button onClick={onLogout} className="flex items-center gap-2 rounded-lg p-1.5 hover:bg-slate-50"><div className="flex size-8 items-center justify-center rounded-full bg-[#e7edff] text-xs font-bold text-[#102a72]">MC</div><span className="hidden text-left sm:block"><span className="block text-xs font-semibold">{user.name}</span><span className="block text-[10px] text-slate-400">{user.plan}</span></span><ChevronDown size={14} className="text-slate-400"/></button></div></header>
}

function Landing({ onDemo, onPricing, pricing }: { onLogin: () => void; onDemo: (plan?: "Free" | "Premium") => void; onPricing: () => void; pricing: boolean }) {
  const [faq, setFaq] = useState<number | null>(0)
  const [showAuth, setShowAuth] = useState(false)
  const [authMode, setAuthMode] = useState<"Entrar" | "Criar conta">("Entrar")
  const [authPlan, setAuthPlan] = useState<"Free" | "Premium">("Free")
  const faqs = [["Como a FutMath ajuda clubes menores?", "Centralizamos informações de scouting e estatísticas demonstrativas para apoiar a análise, sem exigir grandes equipes de dados."], ["Os dados desta demonstração são reais?", "Não. Jogadores e estatísticas são fictícios e servem exclusivamente para demonstrar as funcionalidades da plataforma."], ["Preciso de cartão para começar?", "Não. O modo demonstrativo Free pode ser acessado sem cartão ou compromisso."], ["Como os dados serão atualizados?", "A arquitetura já prevê conexão com provedores e APIs licenciadas. Nenhuma integração esportiva está ativa nesta demonstração."]]
  return <main className="min-h-screen bg-[#f8fafc] text-[#132246]"><header className="flex h-[78px] items-center justify-between border-b border-slate-200/70 bg-white px-5 sm:px-10 lg:px-[8%]"><button onClick={() => onPricing()} className="flex items-center gap-2.5"><div className="flex size-9 items-center justify-center rounded-xl bg-[#102a72] text-white"><Activity size={21}/></div><span className="text-xl font-extrabold tracking-tight">Fut<span className="text-[#20a86d]">Math</span></span></button><nav className="hidden items-center gap-8 text-sm text-slate-600 md:flex"><a href="#como-funciona">Como funciona</a><a href="#beneficios">Benefícios</a><button onClick={onPricing}>Planos</button></nav><div className="flex items-center gap-3"><button onClick={() => { setAuthMode("Entrar"); setShowAuth(true) }} className="hidden text-sm font-semibold text-[#102a72] sm:block">Entrar</button><button onClick={() => onDemo("Free")} className="rounded-lg bg-[#102a72] px-4 py-2.5 text-sm font-semibold text-white hover:bg-[#193b90]">Experimentar grátis <ArrowRight size={15} className="ml-1 inline"/></button></div></header>
    <section className="relative overflow-hidden px-5 pb-20 pt-16 sm:px-10 sm:pt-24 lg:px-[8%]"><div className="absolute -right-32 -top-16 size-[500px] rounded-full bg-[#e7f8f0] blur-3xl"/><div className="relative mx-auto grid max-w-7xl items-center gap-12 lg:grid-cols-[1.05fr_.95fr]"><div><div className="mb-6 inline-flex items-center gap-2 rounded-full border border-[#c8efdc] bg-white px-3 py-1.5 text-xs font-semibold text-[#218756]"><span className="size-2 rounded-full bg-[#2dce89]"/> INTELIGÊNCIA ESPORTIVA ACESSÍVEL</div><h1 className="max-w-[700px] text-[42px] font-extrabold leading-[1.08] tracking-[-.04em] text-[#102a72] sm:text-[56px] lg:text-[64px]">O próximo grande talento pode estar <span className="text-[#20a86d]">onde ninguém está olhando.</span></h1><p className="mt-6 max-w-[560px] text-base leading-7 text-slate-600 sm:text-lg">Descubra, analise e compare jogadores com inteligência esportiva acessível para clubes de todos os tamanhos.</p><div className="mt-8 flex flex-wrap gap-3"><button onClick={() => onDemo("Free")} className="rounded-xl bg-[#102a72] px-6 py-3.5 text-sm font-bold text-white shadow-lg shadow-blue-900/15 hover:bg-[#193b90]">Começar gratuitamente <ArrowRight size={16} className="ml-2 inline"/></button><button onClick={() => onDemo("Free")} className="rounded-xl border border-slate-200 bg-white px-6 py-3.5 text-sm font-bold text-[#102a72] hover:border-[#2dce89]">Explorar a plataforma</button></div><div className="mt-8 flex items-center gap-3 text-xs text-slate-500"><div className="flex -space-x-2"><span className="flex size-7 items-center justify-center rounded-full border-2 border-white bg-[#dbeafe] text-[9px] font-bold">FC</span><span className="flex size-7 items-center justify-center rounded-full border-2 border-white bg-[#dcfce7] text-[9px] font-bold">SC</span><span className="flex size-7 items-center justify-center rounded-full border-2 border-white bg-[#fef3c7] text-[9px] font-bold">AC</span></div>Feita para quem acredita no futebol brasileiro</div></div>
      <div className="relative rounded-[26px] border border-slate-200 bg-white p-3 shadow-[0_28px_80px_-30px_rgba(16,42,114,.25)]"><div className="rounded-[18px] bg-[#f6f8fc] p-4 sm:p-6"><div className="flex items-center justify-between"><div><div className="text-xs font-semibold text-slate-400">PAINEL DE SCOUTING</div><div className="mt-1 text-lg font-bold text-[#15254a]">Visão geral</div></div><div className="rounded-lg bg-white px-3 py-2 text-xs text-slate-500">Temporada 2025 <ChevronDown size={13} className="ml-2 inline"/></div></div><div className="mt-5 grid grid-cols-3 gap-3"><MiniStat title="Atletas" value="1.284" change="+12,8%"/><MiniStat title="Clubes" value="48" change="+4"/><MiniStat title="Competições" value="12" change="+2"/></div><div className="mt-4 rounded-xl bg-white p-4"><div className="mb-3 flex items-center justify-between"><span className="text-xs font-bold">Evolução de desempenho</span><span className="text-[10px] text-slate-400">Últimos 6 meses</span></div><div className="h-[150px]"><ResponsiveContainer width="100%" height="100%"><AreaChart data={historyForPlayer("atleta-12")}><defs><linearGradient id="heroFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#2dce89" stopOpacity={.22}/><stop offset="100%" stopColor="#2dce89" stopOpacity={0}/></linearGradient></defs><CartesianGrid vertical={false} stroke="#eef1f5"/><XAxis dataKey="month" axisLine={false} tickLine={false} tick={{ fontSize: 10, fill: "#94a3b8" }}/><YAxis hide domain={[5, 9]}/><Area type="monotone" dataKey="rating" stroke="#1db178" strokeWidth={2.5} fill="url(#heroFill)"/></AreaChart></ResponsiveContainer></div></div><div className="mt-3 flex items-center gap-3 rounded-xl border border-slate-100 bg-white p-3"><div className="flex size-9 items-center justify-center rounded-full bg-[#e9efff] text-xs font-bold text-[#102a72]">RA</div><div className="min-w-0 flex-1"><div className="text-xs font-bold">Rafael Almeida</div><div className="text-[10px] text-slate-400">Meio-campista · Ferroviária</div></div><span className="rounded-full bg-[#e6f8ef] px-2.5 py-1 text-[10px] font-bold text-[#218756]">Em evolução</span><ArrowUpRight size={15} className="text-[#20a86d]"/></div></div><div className="absolute -bottom-5 -left-5 hidden rounded-xl bg-white p-3 shadow-xl sm:flex sm:items-center sm:gap-2"><span className="flex size-8 items-center justify-center rounded-lg bg-[#e6f8ef] text-[#1c9f68]"><TrendingUp size={17}/></span><span><span className="block text-[10px] text-slate-400">Índice de evolução</span><strong className="text-sm">+18,6%</strong></span></div></div></div></section>
    <section id="como-funciona" className="bg-white px-5 py-16 sm:px-10 lg:px-[8%]"><div className="mx-auto max-w-7xl"><div className="max-w-2xl"><div className="text-xs font-bold tracking-widest text-[#20a86d]">DO DADO À DECISÃO</div><h2 className="mt-3 text-3xl font-extrabold tracking-tight text-[#102a72] sm:text-4xl">Encontre clareza em cada observação.</h2><p className="mt-4 leading-7 text-slate-500">No futebol, boas decisões começam com informação organizada e contexto.</p></div><div className="mt-9 grid gap-5 md:grid-cols-3">{[[Search,"01","Pesquise","Explore atletas de competições nacionais e estaduais com filtros que fazem sentido para a sua realidade."],[ChartNoAxesCombined,"02","Compare","Analise indicadores lado a lado e entenda o contexto por trás dos números."],[Target,"03","Decida","Organize relatórios e compartilhe análises com toda a sua equipe."]].map(([Icon,num,title,body]) => {const I=Icon as typeof Search;return <article key={String(num)} className="rounded-2xl border border-slate-100 bg-[#f9fafc] p-6"><div className="flex items-center justify-between"><span className="flex size-11 items-center justify-center rounded-xl bg-[#e9efff] text-[#102a72]"><I size={21}/></span><span className="text-sm font-bold text-slate-300">{num as string}</span></div><h3 className="mt-6 font-bold text-[#142650]">{title as string}</h3><p className="mt-2 text-sm leading-6 text-slate-500">{body as string}</p></article>})}</div></div></section>
    <section id="beneficios" className="px-5 py-16 sm:px-10 lg:px-[8%]"><div className="mx-auto grid max-w-7xl gap-10 lg:grid-cols-2 lg:items-center"><div><div className="text-xs font-bold tracking-widest text-[#20a86d]">SCOUTING COM MAIS CONTEXTO</div><h2 className="mt-3 text-3xl font-extrabold tracking-tight text-[#102a72] sm:text-4xl">Estrutura profissional para clubes de todos os tamanhos.</h2><p className="mt-4 text-slate-500 leading-7">Menos incerteza, mais tempo para observar o que importa. A FutMath conecta estatísticas, evolução e relatórios num espaço de trabalho simples.</p><div className="mt-7 grid gap-4 sm:grid-cols-2">{[[Goal,"Descoberta de talentos"],[Activity,"Dados centralizados"],[BookOpen,"Relatórios compartilháveis"],[ShieldCheck,"Decisões com contexto"]].map(([Icon,label])=>{const I=Icon as typeof Goal;return <div key={String(label)} className="flex items-center gap-3 text-sm font-semibold text-[#26375e]"><I size={18} className="text-[#20a86d]"/>{label as string}</div>})}</div></div><div className="rounded-3xl bg-[#102a72] p-7 text-white"><div className="text-xs font-semibold tracking-widest text-[#51dfaa]">DEMO INTERATIVA</div><h3 className="mt-3 text-2xl font-bold">Explore a base fictícia da FutMath.</h3><p className="mt-3 text-sm leading-6 text-white/65">Teste filtros, compare jogadores, salve favoritos e gere relatórios sem compromisso.</p><button onClick={() => onDemo("Free")} className="mt-6 rounded-lg bg-[#2dce89] px-5 py-3 text-sm font-bold text-[#102a72]">Entrar na demonstração <ArrowRight size={15} className="ml-2 inline"/></button><div className="mt-7 flex gap-6 border-t border-white/15 pt-5"><div><b className="block text-2xl">60+</b><span className="text-xs text-white/50">atletas fictícios</span></div><div><b className="block text-2xl">12</b><span className="text-xs text-white/50">clubes brasileiros</span></div><div><b className="block text-2xl">3</b><span className="text-xs text-white/50">competições</span></div></div></div></div></section>
    <section className="bg-white px-5 py-16 sm:px-10 lg:px-[8%]"><div className="mx-auto max-w-7xl"><div className="text-center"><div className="text-xs font-bold tracking-widest text-[#20a86d]">PLANOS CLAROS</div><h2 className="mt-3 text-3xl font-extrabold text-[#102a72]">Comece no seu ritmo.</h2></div><div className="mx-auto mt-9 grid max-w-3xl gap-5 md:grid-cols-2">{[["Free","R$ 0","Para conhecer a plataforma",["100 consultas por dia","Pesquisa de atletas","Comparação de estatísticas","Favoritos e relatórios"]],["Premium","R$ 97","Para equipes em crescimento",["Consultas sem limite diário","Tudo do plano Free","Acesso ampliado às funcionalidades","Suporte prioritário"]]].map(([name,price,desc,features])=><div key={String(name)} className={`rounded-2xl border p-6 ${name==="Premium"?"border-[#102a72] bg-[#102a72] text-white":"border-slate-200 bg-white"}`}><div className="flex items-center justify-between"><h3 className="font-bold">{name as string}</h3>{name==="Premium"&&<span className="rounded-full bg-[#2dce89] px-2.5 py-1 text-[10px] font-bold text-[#102a72]">MAIS RECURSOS</span>}</div><div className="mt-4 text-3xl font-extrabold">{price as string}<span className="text-sm font-normal opacity-60">{name==="Premium"?" / mês":""}</span></div><p className="mt-2 text-sm opacity-65">{desc as string}</p><div className="mt-5 flex flex-col gap-3">{(features as string[]).map((item)=><div key={item} className="flex gap-2 text-sm"><Check size={16} className="shrink-0 text-[#2dce89]"/>{item}</div>)}</div><button onClick={() => onDemo("Free")} className={`mt-6 w-full rounded-lg px-4 py-3 text-sm font-bold ${name==="Premium"?"bg-[#2dce89] text-[#102a72]":"bg-[#edf1fc] text-[#102a72]"}`}>{name==="Premium"?"Experimentar Premium":"Começar grátis"}</button></div>)}</div></div></section>
    <section className="px-5 py-16 sm:px-10 lg:px-[8%]"><div className="mx-auto max-w-3xl"><h2 className="text-center text-3xl font-extrabold text-[#102a72]">Perguntas frequentes</h2><div className="mt-7 divide-y divide-slate-200">{faqs.map(([q,a],i)=><button key={q} onClick={()=>setFaq(faq===i?null:i)} className="w-full py-5 text-left"><span className="flex items-center justify-between font-semibold">{q}<ChevronDown className={`transition ${faq===i?"rotate-180":""}`} size={17}/></span>{faq===i&&<span className="mt-3 block max-w-2xl text-sm leading-6 text-slate-500">{a}</span>}</button>)}</div></div></section>
    {showAuth && <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/55 p-4" role="presentation" onMouseDown={(event) => { if (event.target === event.currentTarget) setShowAuth(false) }}><section role="dialog" aria-modal="true" aria-labelledby="auth-title" className="w-full max-w-md rounded-2xl bg-white p-6 shadow-2xl"><div className="flex items-start justify-between"><div><h2 id="auth-title" className="text-xl font-bold text-[#102a72]">{authMode} na FutMath</h2><p className="mt-1 text-sm text-slate-500">Acesso demonstrativo, sem autenticação real.</p></div><button onClick={() => setShowAuth(false)} aria-label="Fechar" className="rounded-lg p-2 text-slate-500 hover:bg-slate-100"><X size={18}/></button></div><form className="mt-6 flex flex-col gap-4" onSubmit={(event) => { event.preventDefault(); setShowAuth(false); onDemo(authPlan) }}>{authMode === "Criar conta" && <label className="flex flex-col gap-1.5 text-sm font-medium text-slate-700">Nome<input required minLength={2} autoComplete="name" className="h-11 rounded-lg border border-slate-200 px-3" placeholder="Seu nome"/></label>}<label className="flex flex-col gap-1.5 text-sm font-medium text-slate-700">E-mail<input type="email" required autoComplete="email" className="h-11 rounded-lg border border-slate-200 px-3" placeholder="voce@clube.com.br"/></label><label className="flex flex-col gap-1.5 text-sm font-medium text-slate-700">Senha<input type="password" required minLength={6} autoComplete={authMode === "Entrar" ? "current-password" : "new-password"} className="h-11 rounded-lg border border-slate-200 px-3" placeholder="Mínimo de 6 caracteres"/></label><label className="flex flex-col gap-1.5 text-sm font-medium text-slate-700">Perfil demonstrativo<select value={authPlan} onChange={(event) => setAuthPlan(event.target.value as "Free" | "Premium")} className="h-11 rounded-lg border border-slate-200 bg-white px-3"><option value="Free">Free · 100 consultas por dia</option><option value="Premium">Premium · consultas sem limite</option></select></label><button type="submit" className="mt-1 rounded-lg bg-[#102a72] px-4 py-3 text-sm font-bold text-white">{authMode === "Entrar" ? "Entrar na demonstração" : "Criar conta demonstrativa"}</button></form><p className="mt-5 text-center text-sm text-slate-500">{authMode === "Entrar" ? "Ainda não tem conta?" : "Já tem conta?"} <button className="font-semibold text-[#102a72] underline" onClick={() => setAuthMode(authMode === "Entrar" ? "Criar conta" : "Entrar")}>{authMode === "Entrar" ? "Cadastre-se" : "Entrar"}</button></p></section></div>}
    <footer className="bg-[#102a72] px-5 py-8 text-white sm:px-10 lg:px-[8%]"><div className="mx-auto flex max-w-7xl flex-col justify-between gap-4 sm:flex-row sm:items-center"><div className="flex items-center gap-2 font-bold"><Activity size={19} className="text-[#2dce89]"/>FutMath</div><span className="text-xs text-white/55">Inteligência esportiva ao alcance de todos.</span><span className="text-[11px] text-white/45">Dados fictícios para demonstração · © 2025 FutMath</span></div></footer>
  </main>
}
function MiniStat({title,value,change}:{title:string;value:string;change:string}) { return <div className="rounded-xl bg-white p-3"><div className="text-[10px] text-slate-400">{title}</div><div className="mt-1 flex items-end justify-between"><strong className="text-xl text-[#102a72]">{value}</strong><span className="text-[9px] font-semibold text-[#218756]">{change}</span></div></div> }

function PageHeading({ eyebrow, title, description, action }: { eyebrow?: string; title: string; description?: string; action?: React.ReactNode }) { return <div className="mb-6 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div>{eyebrow && <div className="mb-2 text-[10px] font-bold tracking-[.16em] text-[#229d68]">{eyebrow}</div>}<h1 className="text-[25px] font-extrabold tracking-tight text-[#15264d] dark:text-white sm:text-[30px]">{title}</h1>{description && <p className="mt-1.5 text-sm text-slate-500 dark:text-slate-400">{description}</p>}</div>{action}</div> }
function Card({children,className=""}:{children:React.ReactNode;className?:string}) { return <section className={`rounded-2xl border border-slate-200/80 bg-white p-5 shadow-[0_2px_9px_rgba(16,42,114,.025)] dark:border-slate-800 dark:bg-[#101b2d] ${className}`}>{children}</section> }
function Dashboard(props: Shared) {
  const {user, go, favoriteIds, openPlayer, quota}=props
  const players = props.playerCatalog
  const trend = historyForPlayer("atleta-9")
  const positionCounts = ["Goleiro","Zagueiro","Lateral","Meio-campista","Atacante"].map((position) => ({ position: position === "Meio-campista" ? "Meio" : position, total: players.filter((p) => p.position === position).length }))
  const highlights = players.filter((p) => p.rating >= 8.4).slice(0, 4)
  return <><PageHeading eyebrow={new Intl.DateTimeFormat("pt-BR", { weekday: "long", day: "numeric", month: "long", year: "numeric" }).format(new Date()).toLocaleUpperCase("pt-BR")} title={`Bom dia, ${user.name.split(" ")[0]}`} description="Aqui está o resumo do seu espaço de scouting." action={<button onClick={()=>go("players")} className="rounded-lg bg-[#102a72] px-4 py-2.5 text-sm font-semibold text-white">Explorar atletas <ArrowRight className="ml-2 inline" size={15}/></button>}/>
    <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><MetricCard icon={Users} label="Atletas na base" value={fmt(players.length)} note="Em 3 competições" color="blue"/><MetricCard icon={Heart} label="Atletas favoritados" value={fmt(favoriteIds.length)} note="Na sua lista" color="green"/><MetricCard icon={ChartNoAxesCombined} label="Comparações" value={fmt(Math.max(3, props.reports.length + 1))} note="Neste espaço" color="purple"/><MetricCard icon={BookOpen} label="Relatórios" value={fmt(props.reports.length)} note="Salvos" color="amber"/></div>
    <div className="mt-5 grid gap-5 xl:grid-cols-[1.55fr_1fr]"><Card><div className="flex items-start justify-between"><div><h2 className="text-sm font-bold">Evolução de desempenho</h2><p className="mt-1 text-xs text-slate-400">Média do índice dos atletas em observação</p></div><button className="rounded-lg border border-slate-200 px-3 py-1.5 text-xs text-slate-500">Últimos 6 meses <ChevronDown className="ml-2 inline" size={13}/></button></div><div className="mt-4 h-[245px]"><ResponsiveContainer width="100%" height="100%"><AreaChart data={trend}><defs><linearGradient id="ratingFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#2dce89" stopOpacity={.18}/><stop offset="100%" stopColor="#2dce89" stopOpacity={0}/></linearGradient></defs><CartesianGrid vertical={false} stroke="#edf0f5"/><XAxis dataKey="month" axisLine={false} tickLine={false} tick={{fontSize:11,fill:"#94a3b8"}}/><YAxis domain={[5,9]} axisLine={false} tickLine={false} tick={{fontSize:11,fill:"#94a3b8"}}/><Tooltip contentStyle={{borderRadius:12,border:"1px solid #e2e8f0",fontSize:12}}/><Area type="monotone" dataKey="rating" name="Índice" stroke="#1eaa73" strokeWidth={2.5} fill="url(#ratingFill)"/></AreaChart></ResponsiveContainer></div></Card><Card><div className="flex items-start justify-between"><div><h2 className="text-sm font-bold">Atletas por posição</h2><p className="mt-1 text-xs text-slate-400">Distribuição na base demonstrativa</p></div><button aria-label="Mais opções" className="rounded p-1 text-slate-400"><MoreHorizontal size={18}/></button></div><div className="mt-3 h-[205px]"><ResponsiveContainer width="100%" height="100%"><BarChart data={positionCounts} layout="vertical" margin={{left:0,right:12}}><CartesianGrid horizontal={false} stroke="#edf0f5"/><XAxis type="number" hide/><YAxis type="category" dataKey="position" axisLine={false} tickLine={false} tick={{fontSize:11,fill:"#64748b"}} width={94}/><Tooltip cursor={false}/><Bar dataKey="total" name="Atletas" fill="#102a72" radius={[0,5,5,0]} barSize={17}/></BarChart></ResponsiveContainer></div><div className="flex items-center gap-2 border-t border-slate-100 pt-3 text-xs text-slate-500"><span className="size-2 rounded-full bg-[#102a72]"/>Base com {players.length} atletas fictícios <span className="ml-auto text-[#218756]">Ver base <ArrowRight size={13} className="inline"/></span></div><button className="absolute inset-0" aria-label="Explorar atletas" onClick={()=>go("players")}/></Card></div>
    <div className="mt-5 grid gap-5 xl:grid-cols-[1.45fr_1fr]"><Card className="p-0"><div className="flex items-center justify-between px-5 py-4"><div><h2 className="text-sm font-bold">Atletas em destaque</h2><p className="mt-1 text-xs text-slate-400">Índice de desempenho na temporada 2025</p></div><button onClick={()=>go("players")} className="text-xs font-semibold text-[#218756]">Ver todos <ArrowRight size={13} className="ml-1 inline"/></button></div><div className="divide-y divide-slate-100 dark:divide-slate-800">{highlights.map((player)=> <PlayerRow key={player.id} player={player} openPlayer={openPlayer} favoriteIds={props.favoriteIds} toggleFavorite={props.toggleFavorite}/>)}</div></Card><div className="flex flex-col gap-5"><Card><div className="flex items-start justify-between"><div><h2 className="text-sm font-bold">Uso do plano</h2><p className="mt-1 text-xs text-slate-400">Consultas realizadas hoje</p></div><span className="rounded-full bg-[#eef2ff] px-2.5 py-1 text-[10px] font-bold text-[#102a72]">{user.plan}</span></div><div className="mt-5 flex items-end justify-between"><strong className="text-2xl">{quota.used}<span className="text-sm font-medium text-slate-400"> / {quota.limit ?? "∞"}</span></strong><span className="text-xs text-slate-400">consultas</span></div><div className="mt-3 h-2 overflow-hidden rounded-full bg-slate-100"><div className="h-full rounded-full bg-[#2dce89]" style={{width:`${Math.min(100,quota.limit?quota.used/quota.limit*100:18)}%`}}/></div><button onClick={()=>go("plan")} className="mt-4 text-xs font-semibold text-[#218756]">Ver detalhes do plano <ArrowRight size={13} className="ml-1 inline"/></button></Card><Card className="bg-[#f2fbf6] dark:bg-[#122b28]"><div className="flex items-center gap-3"><div className="flex size-10 items-center justify-center rounded-xl bg-white text-[#1c9f68] shadow-sm"><Sparkles size={19}/></div><div><h3 className="text-sm font-bold">Uma oportunidade para observar</h3><p className="mt-1 text-[11px] text-slate-500">{highlights[0]?.name} · {highlights[0]?.position}</p></div></div><p className="mt-3 text-xs leading-5 text-slate-500">O índice de desempenho está acima da média da posição nesta base demonstrativa.</p><button onClick={()=>openPlayer(highlights[0])} className="mt-3 text-xs font-semibold text-[#218756]">Ver análise <ArrowRight size={13} className="ml-1 inline"/></button></Card></div></div>
    <div className="mt-5 rounded-2xl border border-[#f2d99a] bg-[#fff9e8] px-4 py-3 text-xs text-[#816728] dark:bg-[#342d1b]">Demonstração: todos os jogadores e dados estatísticos exibidos são fictícios e não representam desempenho real.</div>
  </>
}
function MetricCard({icon:Icon,label,value,note,color}:{icon:typeof Users;label:string;value:string;note:string;color:string}) { const palettes:Record<string,string>={blue:"bg-[#e9efff] text-[#234aab]",green:"bg-[#e6f8ef] text-[#218756]",purple:"bg-[#f3ebff] text-[#8055b6]",amber:"bg-[#fff3dd] text-[#b47920]"};return <Card className="p-4"><div className="flex items-center justify-between"><span className="text-xs font-medium text-slate-500">{label}</span><span className={`flex size-9 items-center justify-center rounded-xl ${palettes[color]}`}><Icon size={18}/></span></div><div className="mt-3 flex items-end justify-between"><strong className="text-[26px] font-extrabold leading-none">{value}</strong><span className="text-[10px] text-slate-400">{note}</span></div></Card> }
function PlayerRow({player,openPlayer,favoriteIds,toggleFavorite,selectable=false,selected=false,onSelect}:{player:Player;openPlayer:(player:Player)=>void;favoriteIds:string[];toggleFavorite:(id:string)=>void;selectable?:boolean;selected?:boolean;onSelect?:()=>void}) { const club=clubFor(player);return <div className="flex items-center gap-3 px-5 py-3.5 hover:bg-slate-50/80 dark:hover:bg-white/[.03]"><div className="flex size-10 shrink-0 items-center justify-center rounded-full bg-[#edf1fc] text-xs font-bold text-[#19377f]">{initials(player.name)}</div><button onClick={()=>openPlayer(player)} className="min-w-0 flex-1 text-left"><span className="block truncate text-xs font-semibold">{player.name}</span><span className="mt-1 block truncate text-[10px] text-slate-400">{player.position} · {club.name}</span></button><div className="hidden w-[64px] text-center sm:block"><span className="block text-xs font-bold">{player.goals}</span><span className="text-[9px] text-slate-400">GOLS</span></div><div className="hidden w-[64px] text-center md:block"><span className="block text-xs font-bold">{player.assists}</span><span className="text-[9px] text-slate-400">AST</span></div><span className="rounded-md bg-[#e6f8ef] px-2 py-1 text-xs font-bold text-[#218756]">{player.rating.toFixed(1)}</span>{selectable?<button onClick={onSelect} className={`flex size-7 items-center justify-center rounded-lg border ${selected?"border-[#102a72] bg-[#102a72] text-white":"border-slate-200 text-slate-400"}`} aria-label={selected?"Remover da comparação":"Adicionar à comparação"}>{selected?<Check size={14}/>:<Plus size={14}/>}</button>:<button onClick={()=>toggleFavorite(player.id)} aria-label={favoriteIds.includes(player.id)?"Remover dos favoritos":"Adicionar aos favoritos"} className={`rounded p-1.5 ${favoriteIds.includes(player.id)?"text-rose-500":"text-slate-300 hover:text-rose-400"}`}><Heart size={16} fill={favoriteIds.includes(player.id)?"currentColor":"none"}/></button>}</div> }

function PlayersPage(props: Shared) {
  const [filters,setFilters]=useState<PlayerFilters>({position:"Todas",sortBy:"rating",sortDirection:"desc"})
  const [page,setPage]=useState(1)
  const [searched,setSearched]=useState("")
  const [minGoals,setMinGoals]=useState("")
  const [minAssists,setMinAssists]=useState("")
  const query=useQuery({queryKey:["players",filters,page],queryFn:async()=>{if(!props.consume()) throw new Error("Cota diária atingida");return playerRepository.listPlayers(filters,{page,pageSize:10})},retry:false})
  const update=(key:keyof PlayerFilters,value:unknown)=>{setFilters(current=>({...current,[key]:value}));setPage(1)}
  const reset=()=>{setFilters({position:"Todas",sortBy:"rating",sortDirection:"desc"});setSearched("");setMinGoals("");setMinAssists("");setPage(1)}
  const filteredCount=query.data?.total??0
  return <><PageHeading eyebrow="SCOUTING · BASE DE ATLETAS" title="Explorar atletas" description="Encontre perfis promissores nas competições que importam para você." action={<button onClick={()=>props.go("compare")} className="rounded-lg bg-[#102a72] px-4 py-2.5 text-sm font-semibold text-white"><ChartNoAxesCombined size={15} className="mr-2 inline"/>Comparar {props.comparisonIds.length>0&&`(${props.comparisonIds.length})`}</button>}/>
    <Card className="mb-4"><div className="flex flex-col gap-3 lg:flex-row"><label className="relative min-w-0 flex-1"><Search size={17} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400"/><input value={searched} onChange={(e)=>{setSearched(e.target.value);update("search",e.target.value||undefined)}} placeholder="Buscar por nome do atleta..." className="h-10 w-full rounded-lg border border-slate-200 bg-white pl-10 pr-3 text-sm outline-none focus:border-[#2dce89]"/></label><label className="flex items-center gap-2 rounded-lg border border-slate-200 px-3 text-xs text-slate-500"><Filter size={15}/><span>Filtros</span></label><select value={filters.sortBy||"rating"} onChange={(e)=>update("sortBy",e.target.value)} className="h-10 rounded-lg border border-slate-200 bg-white px-3 text-xs text-slate-600"><option value="rating">Ordenar: Índice</option><option value="goals">Ordenar: Gols</option><option value="assists">Ordenar: Assistências</option><option value="minutes">Ordenar: Minutos</option><option value="age">Ordenar: Idade</option></select><button onClick={reset} className="h-10 px-2 text-xs font-semibold text-[#218756]">Limpar filtros</button></div>
    <div className="mt-4 grid gap-3 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-6"><select value={filters.position||"Todas"} onChange={(e)=>update("position",e.target.value)} className="h-9 rounded-lg border border-slate-200 bg-white px-3 text-xs text-slate-600"><option>Todas</option>{["Goleiro","Zagueiro","Lateral","Meio-campista","Atacante"].map(x=><option key={x}>{x}</option>)}</select><select value={filters.clubId||""} onChange={(e)=>update("clubId",e.target.value||undefined)} className="h-9 rounded-lg border border-slate-200 bg-white px-3 text-xs text-slate-600"><option value="">Todos os clubes</option>{clubs.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select><select value={filters.competitionId||""} onChange={(e)=>update("competitionId",e.target.value||undefined)} className="h-9 rounded-lg border border-slate-200 bg-white px-3 text-xs text-slate-600"><option value="">Todas competições</option>{competitions.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select><input type="number" min="16" max="45" value={filters.minAge||""} onChange={(e)=>update("minAge",Number(e.target.value)||undefined)} placeholder="Idade mínima" className="h-9 rounded-lg border border-slate-200 px-3 text-xs outline-none focus:border-[#2dce89]"/><input type="number" min="16" max="45" value={filters.maxAge||""} onChange={(e)=>update("maxAge",Number(e.target.value)||undefined)} placeholder="Idade máxima" className="h-9 rounded-lg border border-slate-200 px-3 text-xs outline-none focus:border-[#2dce89]"/><input type="number" value={filters.minMinutes||""} onChange={(e)=>update("minMinutes",Number(e.target.value)||undefined)} placeholder="Mín. minutos" className="h-9 rounded-lg border border-slate-200 px-3 text-xs outline-none focus:border-[#2dce89]"/><input type="number" value={minGoals} onChange={(e)=>{setMinGoals(e.target.value);update("minGoals",Number(e.target.value)||undefined)}} placeholder="Mín. gols" className="h-9 rounded-lg border border-slate-200 px-3 text-xs outline-none focus:border-[#2dce89]"/><input type="number" value={minAssists} onChange={(e)=>{setMinAssists(e.target.value);update("minAssists",Number(e.target.value)||undefined)}} placeholder="Mín. assistências" className="h-9 rounded-lg border border-slate-200 px-3 text-xs outline-none focus:border-[#2dce89]"/></div></Card>
    <Card className="overflow-hidden p-0"><div className="flex items-center justify-between border-b border-slate-100 px-5 py-4"><div><h2 className="text-sm font-bold">Base de atletas <span className="ml-1 rounded-full bg-slate-100 px-2 py-0.5 text-[10px] text-slate-500">{filteredCount}</span></h2><p className="mt-1 text-[11px] text-slate-400">{usingApi ? "Dados fornecidos pela FutMath API" : "Estatísticas fictícias para demonstração"}</p></div><button className="rounded-lg border border-slate-200 px-3 py-2 text-xs text-slate-500"><SlidersHorizontal size={14} className="mr-2 inline"/>Colunas</button></div><div className="grid grid-cols-[minmax(140px,1fr)_90px_75px_70px_70px_85px_50px] gap-2 border-b border-slate-100 bg-slate-50/70 px-5 py-3 text-[9px] font-bold tracking-wider text-slate-400"><span>ATLETA</span><span>POSIÇÃO</span><span className="text-center">JOGOS</span><span className="text-center">GOLS</span><span className="text-center">AST.</span><span className="text-center">ÍNDICE</span><span/></div>{query.isPending?<div className="p-8 text-center text-sm text-slate-400">Carregando atletas...</div>:query.isError?<div className="p-8 text-center text-sm text-rose-500">{query.error.message}</div>:query.data?.items.length?query.data.items.map(player=><div key={player.id} className="grid grid-cols-[minmax(140px,1fr)_90px_75px_70px_70px_85px_50px] items-center gap-2 border-b border-slate-100 px-5 py-2.5 text-xs last:border-0"><button onClick={()=>props.openPlayer(player)} className="flex min-w-0 items-center gap-2.5 text-left"><span className="flex size-8 shrink-0 items-center justify-center rounded-full bg-[#edf1fc] text-[10px] font-bold text-[#19377f]">{initials(player.name)}</span><span className="min-w-0"><b className="block truncate">{player.name}</b><small className="block truncate text-[10px] text-slate-400">{clubFor(player).name} · {player.age} anos</small></span></button><span className="truncate text-slate-500">{player.position}</span><span className="text-center">{player.appearances}</span><span className="text-center">{player.goals}</span><span className="text-center">{player.assists}</span><span className="mx-auto rounded-md bg-[#e6f8ef] px-2 py-1 font-bold text-[#218756]">{player.rating.toFixed(1)}</span><button aria-label="Adicionar à comparação" onClick={()=>props.toggleCompare(player.id)} className={`rounded-md p-1.5 ${props.comparisonIds.includes(player.id)?"bg-[#102a72] text-white":"text-slate-400 hover:bg-slate-100"}`}>{props.comparisonIds.includes(player.id)?<Check size={14}/>:<Plus size={14}/>}</button></div>):<div className="p-12 text-center"><Search size={24} className="mx-auto text-slate-300"/><p className="mt-3 text-sm font-semibold">Nenhum atleta encontrado</p><p className="mt-1 text-xs text-slate-400">Ajuste os filtros para ampliar sua busca.</p></div>}
    <div className="flex items-center justify-between border-t border-slate-100 px-5 py-3 text-xs text-slate-500"><span>Exibindo {query.data?.items.length||0} de {filteredCount} atletas</span><div className="flex items-center gap-2"><button aria-label="Página anterior" disabled={page===1} onClick={()=>setPage(p=>p-1)} className="rounded-md border border-slate-200 p-1.5 disabled:opacity-30"><ChevronLeft size={15}/></button><span>{page} / {Math.max(1,Math.ceil(filteredCount/10))}</span><button aria-label="Próxima página" disabled={page*10>=filteredCount} onClick={()=>setPage(p=>p+1)} className="rounded-md border border-slate-200 p-1.5 disabled:opacity-30"><ChevronRight size={15}/></button></div></div></Card>
    {props.comparisonIds.length>0&&<div className="fixed bottom-4 left-4 right-4 z-20 mx-auto flex max-w-xl items-center justify-between rounded-xl bg-[#102a72] px-4 py-3 text-white shadow-xl lg:left-[calc(248px+1rem)]"><span className="text-sm">{props.comparisonIds.length} atletas selecionados</span><button onClick={()=>props.go("compare")} className="rounded-lg bg-[#2dce89] px-3 py-2 text-xs font-bold text-[#102a72]">Abrir comparação <ArrowRight className="ml-1 inline" size={14}/></button></div>}
  </>
}

function PlayerPage(props: Shared) {
  const p=props.selectedPlayer,club=clubFor(p),competition=compFor(p),history=historyForPlayer(p.id)
  const minutesPerGoal=p.goals?p.minutes/p.goals:null, goalsPer90=p.minutes?(p.goals+p.assists)/(p.minutes/90):null
  return <><button onClick={()=>props.go("players")} className="mb-5 text-xs font-semibold text-slate-500"><ChevronLeft size={14} className="mr-1 inline"/>Voltar para atletas</button><Card className="overflow-hidden p-0"><div className="h-28 bg-gradient-to-r from-[#102a72] to-[#1c4b9b]"/><div className="-mt-12 flex flex-col gap-4 px-5 pb-5 sm:flex-row sm:items-end sm:px-7"><div className="flex size-24 shrink-0 items-center justify-center rounded-2xl border-4 border-white bg-[#e9efff] text-2xl font-extrabold text-[#102a72]">{initials(p.name)}</div><div className="min-w-0 flex-1 pb-1"><div className="flex flex-wrap items-center gap-2"><h1 className="text-2xl font-extrabold">{p.name}</h1><span className="rounded-full bg-[#e6f8ef] px-2.5 py-1 text-[10px] font-bold text-[#218756]">{p.position}</span></div><div className="mt-1 text-sm text-slate-500">{club.name} · {competition.name}</div><div className="mt-2 text-xs text-slate-400">{p.age} anos · {p.nationality} · Temporada {p.season}</div></div><div className="flex gap-2 pb-1"><button onClick={()=>props.toggleFavorite(p.id)} className="rounded-lg border border-slate-200 px-3 py-2 text-xs font-semibold"><Heart size={15} className={`mr-1.5 inline ${props.favoriteIds.includes(p.id)?"fill-rose-500 text-rose-500":""}`}/>Favoritar</button><button onClick={()=>props.toggleCompare(p.id)} className="rounded-lg bg-[#102a72] px-3 py-2 text-xs font-semibold text-white"><Plus size={15} className="mr-1.5 inline"/>Comparar</button></div></div></Card>
  <div className="mt-5 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><MetricCard icon={Activity} label="Partidas" value={fmt(p.appearances)} note="na temporada" color="blue"/><MetricCard icon={Clock3} label="Minutos" value={fmt(p.minutes)} note="em campo" color="green"/><MetricCard icon={Goal} label="Gols · assistências" value={`${p.goals} · ${p.assists}`} note="participações" color="purple"/><MetricCard icon={Target} label="Índice de desempenho" value={p.rating.toFixed(1)} note="escala demonstrativa" color="amber"/></div>
  <div className="mt-5 grid gap-5 xl:grid-cols-[1.5fr_1fr]"><Card><h2 className="text-sm font-bold">Evolução recente</h2><p className="mt-1 text-xs text-slate-400">Índice demonstrativo por mês</p><div className="mt-5 h-[250px]"><ResponsiveContainer width="100%" height="100%"><AreaChart data={history}><CartesianGrid vertical={false} stroke="#edf0f5"/><XAxis dataKey="month" axisLine={false} tickLine={false} tick={{fontSize:11,fill:"#94a3b8"}}/><YAxis domain={[5,9]} axisLine={false} tickLine={false} tick={{fontSize:11,fill:"#94a3b8"}}/><Tooltip/><Area type="monotone" dataKey="rating" name="Índice" stroke="#1eaa73" fill="#dff6e9" strokeWidth={2}/></AreaChart></ResponsiveContainer></div></Card><Card><h2 className="text-sm font-bold">Indicadores derivados</h2><p className="mt-1 text-xs text-slate-400">Calculados a partir dos dados disponíveis</p><div className="mt-5 flex flex-col gap-4">{[["Finalizações",fmt(p.shots)],["Minutos por gol",minutesPerGoal?`${Math.round(minutesPerGoal)} min`:"Dados indisponíveis"],["Participações em gol / 90 min",goalsPer90?goalsPer90.toFixed(2):"Dados indisponíveis"],["Campeonato",competition.name],["Temporada",p.season]].map(([label,value])=><div key={label} className="flex justify-between border-b border-slate-100 pb-3 text-xs last:border-0"><span className="text-slate-500">{label}</span><b className="max-w-[60%] text-right">{value}</b></div>)}</div></Card></div>
  <Card className="mt-5"><h2 className="text-sm font-bold">Origem dos dados</h2><div className="mt-4 grid gap-3 text-xs sm:grid-cols-4"><div><span className="text-slate-400">Fonte</span><b className="mt-1 block">{p.source.sourceName}</b></div><div><span className="text-slate-400">Atualização</span><b className="mt-1 block">{new Date(p.source.updatedAt).toLocaleDateString("pt-BR")}</b></div><div><span className="text-slate-400">Competição</span><b className="mt-1 block">{competition.name}</b></div><div><span className="text-slate-400">Qualidade</span><b className="mt-1 block">Fictício · demonstração</b></div></div><p className="mt-4 rounded-lg bg-amber-50 p-3 text-[11px] text-amber-800">Os dados deste perfil foram gerados artificialmente e não representam um jogador ou desempenho real.</p></Card></>
}

function ComparePage(props: Shared) {
  const [season,setSeason]=useState("2025")
  const candidates=props.playerCatalog.filter(p=>props.comparisonIds.includes(p.id))
  const chartData=[{metric:"Gols",...Object.fromEntries(candidates.map(p=>[p.name,p.goals]))},{metric:"Assistências",...Object.fromEntries(candidates.map(p=>[p.name,p.assists]))},{metric:"Partidas",...Object.fromEntries(candidates.map(p=>[p.name,p.appearances]))},{metric:"Finalizações",...Object.fromEntries(candidates.map(p=>[p.name,p.shots]))}]
  const radarMetrics=[{metric:"Índice",key:"rating",max:10},{metric:"Gols / 90",key:"goals90",max:1.2},{metric:"Assist. / 90",key:"assists90",max:.8},{metric:"Minutos",key:"minutes",max:2500},{metric:"Finalizações / 90",key:"shots90",max:4}]
  const radarData=radarMetrics.map(metric=>({metric:metric.metric,...Object.fromEntries(candidates.map(p=>{const raw=metric.key==="goals90"?p.goals/(p.minutes/90||1):metric.key==="assists90"?p.assists/(p.minutes/90||1):metric.key==="shots90"?p.shots/(p.minutes/90||1):p[metric.key as keyof Player] as number;return [p.name,Math.max(0,Math.min(100,raw/metric.max*100))]}))}))
  const colors=["#102a72","#2dce89","#9063d5","#f3a83b"]
  const leagues=[...new Set(candidates.map(p=>p.competitionId))]
  return <><PageHeading eyebrow="ANÁLISE COMPARATIVA" title="Comparar atletas" description="Compare indicadores lado a lado, sempre considerando contexto e competição." action={<button onClick={props.createReport} disabled={candidates.length<2} className="rounded-lg bg-[#102a72] px-4 py-2.5 text-sm font-semibold text-white disabled:opacity-40"><Download size={15} className="mr-2 inline"/>Gerar relatório</button>}/>
    {candidates.length<2&&<Card className="mb-5 border-dashed border-[#b9c7e9] bg-[#f7f9ff] text-center"><div className="mx-auto flex size-11 items-center justify-center rounded-xl bg-[#e9efff] text-[#102a72]"><ChartNoAxesCombined size={22}/></div><h2 className="mt-3 text-sm font-bold">Selecione de 2 a 4 atletas para comparar</h2><p className="mx-auto mt-1 max-w-lg text-xs text-slate-500">Adicione jogadores na exploração e acompanhe os indicadores comparáveis numa única visualização.</p><button onClick={()=>props.go("players")} className="mt-4 rounded-lg bg-[#102a72] px-4 py-2 text-xs font-semibold text-white">Explorar atletas <ArrowRight size={14} className="ml-1 inline"/></button></Card>}
    <div className="mb-4 flex items-center justify-between"><span className="text-xs text-slate-500">{candidates.length} de 4 atletas</span><select aria-label="Temporada" value={season} onChange={e=>setSeason(e.target.value)} className="h-9 rounded-lg border border-slate-200 bg-white px-3 text-xs"><option>2025</option><option>2024</option></select></div>
    {leagues.length>1&&<div className="mb-4 rounded-xl border border-amber-200 bg-amber-50 px-4 py-3 text-xs leading-5 text-amber-900"><strong>Contexto competitivo:</strong> estes atletas disputaram competições diferentes. Nível, calendário e contexto de cada competição podem afetar a interpretação dos indicadores.</div>}
    <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{candidates.map((p,i)=><Card key={p.id} className="relative"><button onClick={()=>props.toggleCompare(p.id)} aria-label={`Remover ${p.name}`} className="absolute right-4 top-4 rounded p-1 text-slate-400 hover:text-rose-500"><X size={16}/></button><div className="flex items-center gap-3"><div className="flex size-12 items-center justify-center rounded-full bg-[#edf1fc] text-sm font-bold text-[#19377f]">{initials(p.name)}</div><div><h3 className="pr-5 text-sm font-bold">{p.name}</h3><p className="mt-1 text-[11px] text-slate-400">{clubFor(p.clubId).name}</p></div></div><div className="mt-4 flex justify-between text-[10px] text-slate-500"><span>{p.position}</span><span>{p.age} anos</span></div><div className="mt-3 flex items-end justify-between border-t border-slate-100 pt-3"><span className="text-[10px] text-slate-400">Índice demonstrativo</span><strong className="text-xl" style={{color:colors[i]}}>{p.rating.toFixed(1)}</strong></div></Card>)}{candidates.length<4&&<button onClick={()=>props.go("players")} className="flex min-h-[140px] flex-col items-center justify-center rounded-2xl border border-dashed border-slate-300 text-xs text-slate-500 hover:border-[#2dce89] hover:text-[#218756]"><Plus size={21}/><span className="mt-2">Adicionar atleta</span></button>}</div>
    {candidates.length>=2&&<><div className="mt-5 grid gap-5 xl:grid-cols-2"><Card><h2 className="text-sm font-bold">Indicadores selecionados</h2><p className="mt-1 text-xs text-slate-400">Valores absolutos para leitura contextualizada</p><div className="mt-4 h-[270px]"><ResponsiveContainer width="100%" height="100%"><BarChart data={chartData} margin={{top:10,right:10,left:-15,bottom:0}}><CartesianGrid vertical={false} stroke="#edf0f5"/><XAxis dataKey="metric" axisLine={false} tickLine={false} tick={{fontSize:10,fill:"#64748b"}}/><YAxis axisLine={false} tickLine={false} tick={{fontSize:10,fill:"#94a3b8"}}/><Tooltip/><LegendSimple candidates={candidates} colors={colors}/>{candidates.map((p,i)=><Bar key={p.id} dataKey={p.name} fill={colors[i]} radius={[4,4,0,0]} barSize={22}/>)}</BarChart></ResponsiveContainer></div></Card><Card><h2 className="text-sm font-bold">Radar normalizado</h2><p className="mt-1 text-xs text-slate-400">Indicadores relativos, escala 0–100 (demonstração)</p><div className="mt-4 h-[270px]"><ResponsiveContainer width="100%" height="100%"><RadarChart data={radarData} outerRadius="72%"><PolarGrid stroke="#e6eaf0"/><PolarAngleAxis dataKey="metric" tick={{fontSize:10,fill:"#64748b"}}/>{candidates.map((p,i)=><Radar key={p.id} name={p.name} dataKey={p.name} stroke={colors[i]} fill={colors[i]} fillOpacity={.1}/>)}</RadarChart></ResponsiveContainer></div><p className="text-[10px] text-slate-400">A normalização usa limites demonstrativos fixos e não define qualidade nem superioridade.</p></Card></div><Card className="mt-5 overflow-x-auto p-0"><table className="w-full min-w-[600px] text-xs"><thead className="bg-slate-50 text-left text-[10px] tracking-wide text-slate-400"><tr><th className="px-5 py-3">INDICADOR</th>{candidates.map(p=><th key={p.id} className="px-4 py-3">{p.name}</th>)}</tr></thead><tbody>{[["Clube",(p:Player)=>clubFor(p.clubId).name],["Competição",(p:Player)=>compFor(p.competitionId).name],["Temporada",(p:Player)=>p.season],["Partidas",(p:Player)=>p.appearances],["Minutos",(p:Player)=>fmt(p.minutes)],["Gols",(p:Player)=>p.goals],["Assistências",(p:Player)=>p.assists],["Finalizações",(p:Player)=>p.shots],["Gols por 90 min",(p:Player)=>(p.goals/(p.minutes/90||1)).toFixed(2)],["Assistências por 90 min",(p:Player)=>(p.assists/(p.minutes/90||1)).toFixed(2)],["Índice",(p:Player)=>p.rating.toFixed(1)]].map(([label,value])=><tr key={String(label)} className="border-t border-slate-100"><td className="px-5 py-3 font-medium text-slate-500">{String(label)}</td>{candidates.map(p=><td key={p.id} className="px-4 py-3 font-semibold">{(value as (p:Player)=>string|number)(p)}</td>)}</tr>)}</tbody></table></Card></>}
    <p className="mt-4 text-[10px] text-slate-400">Dados fictícios para demonstração. Indicadores não ajustam força do adversário, função tática ou minutos em campo. Não há conclusão automática sobre qual atleta é melhor.</p>
  </>
}
function LegendSimple({candidates,colors}:{candidates:Player[];colors:string[]}) {return <div className="mb-1 flex flex-wrap gap-3">{candidates.map((p,i)=><span key={p.id} className="flex items-center gap-1.5 text-[10px] text-slate-500"><i className="size-2 rounded-full" style={{background:colors[i]}}/>{p.name}</span>)}</div>}

function ClubsPage(props: Shared) {
  const [search,setSearch]=useState("")
  const filtered=clubs.filter(c=>`${c.name} ${c.state}`.toLowerCase().includes(search.toLowerCase()))
  return <><PageHeading eyebrow="REDE DE CLUBES" title="Explorar clubes" description="Conheça os clubes disponíveis na base demonstrativa."/><Card className="mb-5"><label className="relative block max-w-xl"><Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400"/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Buscar clube ou estado..." className="h-10 w-full rounded-lg border border-slate-200 pl-10 pr-3 text-sm outline-none focus:border-[#2dce89]"/></label></Card><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">{filtered.map(club=><button key={club.id} onClick={()=>{props.setSelectedClub(club);props.go("club")}} className="text-left"><Card className="transition hover:-translate-y-0.5 hover:shadow-md"><div className="flex items-center gap-4"><div className="flex size-14 items-center justify-center rounded-2xl text-lg font-extrabold text-white" style={{background:club.color}}>{initials(club.name)}</div><div className="min-w-0"><h2 className="truncate text-sm font-bold">{club.name}</h2><p className="mt-1 text-xs text-slate-400">{club.state} · {compFor(club.competitionId).name}</p></div><ArrowRight className="ml-auto text-slate-300" size={17}/></div><div className="mt-5 flex justify-between border-t border-slate-100 pt-4 text-xs"><span className="text-slate-500">{players.filter(p=>p.clubId===club.id).length} atletas cadastrados</span><b className="text-slate-700">Temporada {club.season}</b></div></Card></button>)}</div>{filtered.length===0&&<EmptyState title="Nenhum clube encontrado" action={()=>setSearch("")}/>}<p className="mt-5 text-[10px] text-slate-400">Clubes reais são listados apenas como contexto. Elencos e estatísticas desta demonstração são fictícios.</p></>
}
function ClubPage(props: Shared) { const club=props.selectedClub, roster=players.filter(p=>p.clubId===club.id),counts=["Goleiro","Zagueiro","Lateral","Meio-campista","Atacante"].map(position=>({position,total:roster.filter(p=>p.position===position).length}));return <><button onClick={()=>props.go("clubs")} className="mb-5 text-xs font-semibold text-slate-500"><ChevronLeft size={14} className="mr-1 inline"/>Voltar para clubes</button><PageHeading eyebrow={`CLUBES · ${club.state}`} title={club.name} description={`${compFor(club.competitionId).name} · Temporada ${club.season}`}/><div className="grid gap-5 xl:grid-cols-[1.3fr_.7fr]"><Card><div className="flex items-center gap-4"><div className="flex size-16 items-center justify-center rounded-2xl text-xl font-bold text-white" style={{background:club.color}}>{initials(club.name)}</div><div><h2 className="text-lg font-bold">{club.name}</h2><p className="text-xs text-slate-400">{club.state} · {roster.length} atletas na base</p></div></div><div className="mt-6 grid grid-cols-3 gap-3">{[["Atletas",roster.length],["Idade média",(roster.reduce((sum,p)=>sum+p.age,0)/(roster.length||1)).toFixed(1)],["Média de índice",(roster.reduce((sum,p)=>sum+p.rating,0)/(roster.length||1)).toFixed(1)]].map(([label,value])=><div key={String(label)} className="rounded-xl bg-slate-50 p-3"><span className="text-[10px] text-slate-400">{label}</span><b className="mt-1 block text-xl">{value}</b></div>)}</div></Card><Card><h2 className="text-sm font-bold">Elenco por posição</h2><div className="mt-4 flex flex-col gap-3">{counts.map(c=><div key={c.position} className="flex items-center gap-3 text-xs"><span className="w-28 text-slate-500">{c.position}</span><span className="h-2 flex-1 overflow-hidden rounded-full bg-slate-100"><i className="block h-full rounded-full bg-[#2dce89]" style={{width:`${c.total/Math.max(1,roster.length)*100}%`}}/></span><b>{c.total}</b></div>)}</div></Card></div><Card className="mt-5 overflow-hidden p-0"><div className="px-5 py-4"><h2 className="text-sm font-bold">Atletas em destaque</h2></div>{roster.sort((a,b)=>b.rating-a.rating).slice(0,8).map(player=><PlayerRow key={player.id} player={player} openPlayer={props.openPlayer} favoriteIds={props.favoriteIds} toggleFavorite={props.toggleFavorite}/>)}</Card></> }

function FavoritesPage(props: Shared) { const list=players.filter(p=>props.favoriteIds.includes(p.id));return <><PageHeading eyebrow="SUA LISTA" title="Atletas favoritos" description={`${list.length} atletas salvos para acompanhar.`} action={<button onClick={()=>props.go("players")} className="rounded-lg bg-[#102a72] px-4 py-2.5 text-sm font-semibold text-white"><Plus size={15} className="mr-1 inline"/>Explorar atletas</button>}/><Card className="overflow-hidden p-0">{list.length?list.map(p=><PlayerRow key={p.id} player={p} openPlayer={props.openPlayer} favoriteIds={props.favoriteIds} toggleFavorite={props.toggleFavorite}/>):<EmptyState title="Sua lista está vazia" description="Salve atletas durante a exploração para encontrá-los rapidamente aqui." action={()=>props.go("players")} actionLabel="Explorar atletas"/>}</Card></> }
function ReportsPage(props: Shared) { return <><PageHeading eyebrow="ANÁLISE E DECISÃO" title="Relatórios" description="Histórico de análises geradas neste espaço de trabalho." action={<button onClick={()=>props.go("compare")} className="rounded-lg bg-[#102a72] px-4 py-2.5 text-sm font-semibold text-white"><Plus size={15} className="mr-1 inline"/>Novo relatório</button>}/><div className="mb-4 rounded-xl border border-amber-200 bg-amber-50 px-4 py-3 text-xs text-amber-900">Os relatórios desta demonstração utilizam dados gerados artificialmente. Exportar PDF abre a visualização de impressão do navegador.</div><Card className="overflow-hidden p-0">{props.reports.length?props.reports.map(report=>{const roster=report.playerIds.map(id=>players.find(p=>p.id===id)).filter(Boolean) as Player[];return <div key={report.id} className="flex flex-col gap-3 border-b border-slate-100 px-5 py-4 last:border-0 sm:flex-row sm:items-center"><div className="flex size-10 items-center justify-center rounded-xl bg-[#edf1fc] text-[#102a72]"><BookOpen size={18}/></div><div className="min-w-0 flex-1"><h2 className="truncate text-sm font-bold">{report.title}</h2><p className="mt-1 text-[11px] text-slate-400">{report.type} · {roster.map(p=>p.name).join(", ")||"Atletas removidos"}</p></div><span className="whitespace-nowrap text-xs text-slate-400">{new Date(report.createdAt).toLocaleDateString("pt-BR")}</span><div className="flex gap-2"><button onClick={()=>props.exportReport(report)} className="rounded-lg border border-slate-200 px-3 py-2 text-xs font-semibold"><Download size={14} className="mr-1 inline"/>PDF</button><button onClick={()=>props.deleteReport(report.id)} aria-label="Excluir relatório" className="rounded-lg border border-slate-200 p-2 text-slate-400 hover:text-rose-500"><X size={15}/></button></div></div>}):<EmptyState title="Nenhum relatório criado" description="Compare atletas e gere seu primeiro relatório." action={()=>props.go("compare")} actionLabel="Comparar atletas"/>}</Card></> }
function EmptyState({title,description,action,actionLabel="Limpar busca"}:{title:string;description?:string;action?:()=>void;actionLabel?:string}) {return <div className="p-12 text-center"><div className="mx-auto flex size-12 items-center justify-center rounded-xl bg-slate-100 text-slate-400"><Search size={21}/></div><h3 className="mt-3 text-sm font-bold">{title}</h3>{description&&<p className="mx-auto mt-1 max-w-sm text-xs text-slate-400">{description}</p>}{action&&<button onClick={action} className="mt-4 rounded-lg bg-[#102a72] px-4 py-2 text-xs font-semibold text-white">{actionLabel}</button>}</div> }
function PlanPage(props: Shared) { const {user,quota}=props;return <><PageHeading eyebrow="ASSINATURA" title="Meu plano" description="Acompanhe seu consumo e conheça as opções da FutMath."/><div className="grid gap-5 xl:grid-cols-[1.2fr_.8fr]"><Card><div className="flex items-start justify-between"><div><span className="text-xs text-slate-400">PLANO ATUAL</span><h2 className="mt-2 text-2xl font-extrabold">{user.plan}</h2><p className="mt-1 text-sm text-slate-500">{user.plan==="Free"?"Acesso gratuito à demonstração":"R$ 97,00 / mês (valor demonstrativo)"}</p></div><span className="flex size-12 items-center justify-center rounded-xl bg-[#e9efff] text-[#102a72]"><Sparkles size={22}/></span></div><div className="mt-6 border-t border-slate-100 pt-5"><div className="flex justify-between text-xs"><span>Consultas realizadas hoje</span><b>{quota.used} / {quota.limit??"Sem limite"}</b></div><div className="mt-3 h-2.5 overflow-hidden rounded-full bg-slate-100"><div className="h-full rounded-full bg-[#2dce89] transition-all" style={{width:`${quota.limit?Math.min(100,quota.used/quota.limit*100):8}%`}}/></div><div className="mt-2 flex justify-between text-[10px] text-slate-400"><span>{quota.limit?`${Math.max(0,quota.limit-quota.used)} consultas restantes`:"Consultas sem limite diário"}</span><span>Renova à meia-noite</span></div></div><div className="mt-5 rounded-xl bg-slate-50 p-4 text-xs leading-5 text-slate-500">No modo demonstrativo, uma consulta à base de atletas consome uma unidade. Favoritar e alterar a interface não consome cota. O limite real deve ser aplicado no backend, não no navegador.</div></Card><Card className="bg-[#102a72] text-white"><div className="flex items-center gap-2 text-xs font-bold tracking-widest text-[#55dfa9]"><Sparkles size={15}/> MAIS INTELIGÊNCIA</div><h2 className="mt-4 text-2xl font-extrabold">FutMath Premium</h2><p className="mt-2 text-sm leading-6 text-white/65">Mais espaço para aprofundar suas análises e acompanhar o mercado.</p><div className="mt-5 text-3xl font-extrabold">R$ 97<span className="text-sm font-medium text-white/60"> / mês</span></div><div className="mt-5 flex flex-col gap-3 text-xs">{["Consultas sem limite diário","Acesso ampliado às funcionalidades","Comparações e relatórios","Fluxo demonstrativo, sem cobrança"].map(item=><span key={item}><Check size={15} className="mr-2 inline text-[#42d89c]"/>{item}</span>)}</div><button onClick={()=>toast("Fluxo demonstrativo",{description:"A assinatura Premium não realiza cobranças nesta versão."})} className="mt-6 w-full rounded-lg bg-[#2dce89] py-3 text-sm font-bold text-[#102a72]">Conhecer o Premium</button><span className="mt-2 block text-center text-[10px] text-white/45">Sem pagamentos reais nesta demonstração.</span></Card></div></> }
function SettingsPage(props: Shared) { const [email,setEmail]=useState("mariana@ferroviaria.com.br");return <><PageHeading eyebrow="PREFERÊNCIAS" title="Configurações" description="Gerencie seu perfil e preferências da demonstração."/><div className="grid gap-5 xl:grid-cols-[1fr_1fr]"><Card><h2 className="text-sm font-bold">Perfil do workspace</h2><p className="mt-1 text-xs text-slate-400">Informações simuladas da conta.</p><div className="mt-5 flex flex-col gap-4"><label className="text-xs font-semibold">Nome<input defaultValue={props.user.name} className="mt-2 h-10 w-full rounded-lg border border-slate-200 px-3 text-sm font-normal outline-none focus:border-[#2dce89]"/></label><label className="text-xs font-semibold">E-mail<input value={email} onChange={e=>setEmail(e.target.value)} type="email" className="mt-2 h-10 w-full rounded-lg border border-slate-200 px-3 text-sm font-normal outline-none focus:border-[#2dce89]"/></label><label className="text-xs font-semibold">Clube<input defaultValue={props.user.club} className="mt-2 h-10 w-full rounded-lg border border-slate-200 px-3 text-sm font-normal outline-none focus:border-[#2dce89]"/></label><button onClick={()=>toast.success("Preferências salvas nesta sessão")} className="self-start rounded-lg bg-[#102a72] px-4 py-2.5 text-xs font-semibold text-white">Salvar alterações</button></div></Card><Card><h2 className="text-sm font-bold">Modo de demonstração</h2><p className="mt-1 text-xs text-slate-400">Escolha um perfil para explorar as experiências dos planos.</p><div className="mt-5 flex flex-col gap-3"><div className="flex items-center justify-between rounded-xl border border-slate-200 p-4"><div><b className="text-sm">Perfil Free</b><span className="mt-1 block text-xs text-slate-400">Limite demonstrativo de 100 consultas/dia</span></div>{props.user.plan==="Free"&&<Check size={18} className="text-[#218756]"/>}<button onClick={async()=>{await authService.signIn("Free");toast.success("Perfil Free ativo")}} className="rounded-lg border px-3 py-2 text-xs">Selecionar</button></div><div className="flex items-center justify-between rounded-xl border border-slate-200 p-4"><div><b className="text-sm">Perfil Premium</b><span className="mt-1 block text-xs text-slate-400">Sem limite diário no modo de demonstração</span></div>{props.user.plan==="Premium"&&<Check size={18} className="text-[#218756]"/>}<button onClick={async()=>{const premium=await authService.signIn("Premium");toast.success(`Perfil ${premium.plan} ativo`)}} className="rounded-lg border px-3 py-2 text-xs">Selecionar</button></div></div><p className="mt-4 rounded-lg bg-amber-50 p-3 text-[11px] leading-5 text-amber-800">A sessão é simulada e não oferece autenticação nem segurança de produção.</p></Card></div><Card className="mt-5"><h2 className="text-sm font-bold">Integração futura</h2><p className="mt-2 text-xs leading-5 text-slate-500">Provedor atual: <code className="rounded bg-slate-100 px-1.5 py-0.5">{process.env.NEXT_PUBLIC_DATA_PROVIDER||"mock"}</code>. Configure <code>NEXT_PUBLIC_API_BASE_URL</code> e o backend REST antes de selecionar o provedor API. Os endpoints ainda não foram especificados nem implementados.</p></Card></> }
